/**
 * Deletes a directory recursively, including all sub-directories and files.
 *
 * @param directory the directory to delete
 * @throws IOException in case deletion is unsuccessful
 */
private static void deleteDirectory(File directory) throws IOException {
    if (!directory.exists()) {
        return;
    }
    if (!directory.isDirectory()) {
        throw new IOException("Directory does not exist or is not a directory: " + directory);
    }
    for (File file : directory.listFiles()) {
        if (file.isDirectory()) {
            deleteDirectory(file);
        } else {
            if (!file.delete()) {
                throw new IOException("Could not delete file: " + file);
            }
        }
    }
    if (!directory.delete()) {
        throw new IOException("Could not delete directory: " + directory);
    }
}

