public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the day offset
    int dayOffset = (int) ((timeBucket % 10000000) / 10000);
    // Calculate the new day
    int newDay = (dayOffset + dayStep - 1) / dayStep * dayStep;
    // Calculate the new time bucket
    long newTimeBucket = timeBucket - (timeBucket % 10000000) + newDay * 10000;
    return newTimeBucket;
}
