    // Check if the size is valid
    if (size <= 0) {
        throw new IllegalArgumentException("Size must be a positive integer");
    }

    // Calculate the new required capacity
    int newCapacity = this.capacity + size;

    // Check if the new capacity is greater than the max array size
    if (newCapacity > this.maxCapacity) {
        throw new IllegalStateException("Cannot enlarge byte array beyond max size");
    }

    // Create a new array with the new capacity
    byte[] newArray = new byte[newCapacity];

    // Copy the existing elements to the new array
    System.arraycopy(this.array, 0, newArray, 0, this.length);

    // Set the new array and capacity
    this.array = newArray;
    this.capacity = newCapacity;
}

private void enlarge(final int size) {
    // Check for potential issues before proceeding
    if (size < 0) {
        throw new IllegalArgumentException("Invalid size: " + size);
    }

    // Calculate the new capacity required to enlarge the byte vector
    int newCapacity = this.capacity + size;

    // Check if the new capacity exceeds the maximum allowed capacity
    if (newCapacity > this.MAX_CAPACITY) {
        throw new IndexOutOfBoundsException("Maximum capacity exceeded");
    }

    // Create a new array to hold the enlarged byte vector
    byte[] newByteArray = new byte[newCapacity];

    // Copy the contents of the original byte array to the new array
    System.arraycopy(this.byteArray, 0, newByteArray, 0, this.capacity);

    // Update the capacity and byte array reference
    this.capacity = newCapacity;
    this.byteArray = newByteArray;
}

