/**
 * Efficient way to compute the intersection between two sets
 * @param set1 set $1$
 * @param set2 set $2$
 * @return intersection of set $1$ and $2$
 */
public static Set<V> intersection(Set<V> set1, Set<V> set2) {
    // Check if either set is empty
    if (set1.isEmpty() || set2.isEmpty()) {
        return Collections.emptySet();
    }

    // Create a new hash set to store the intersection
    Set<V> intersection = new HashSet<>();

    // Iterate over set 1 and check if the element is present in set 2
    for (V element1 : set1) {
        if (set2.contains(element1)) {
            intersection.add(element1);
        }
    }

    return intersection;
}

