public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Check if there are any vertices in the minimum label bucket
    if (!bucketsByLabel.get(minLabel).isEmpty()) {
        // Move all vertices from the minimum label bucket to the bucket with label 0
        for (int vertex : bucketsByLabel.get(minLabel)) {
            labels.add(0, vertex);
            bucketsByLabel.get(0).add(vertex);
            bucketsByLabel.get(minLabel).remove(vertex);
        }
    }

    // Clear the minimum label bucket
    bucketsByLabel.set(minLabel, new HashSet<>());

    // Update the labeling accordingly
    for (int vertex : labels) {
        int currentLabel = vertex;
        while (bucketsByLabel.get(currentLabel).contains(vertex)) {
            currentLabel++;
        }
        labels.set(labels.indexOf(vertex), currentLabel);
    }
}

