    final List<Class> classContext = new ArrayList<>();
    classContext.add(Thread.currentThread().getContextClassLoader().loadClass(Thread.currentThread().getStackTrace()[2].getClassName()));

    if (classContext.get(0) == null) {
        classContext.add(Class.forName(Thread.currentThread().getStackTrace()[3].getClassName()).getClassLoader().loadClass(Thread.currentThread().getStackTrace()[4].getClassName()));
