/**
 * Atomically moves all {@link ListNode}s from {@code list} to this list by removing each node from {@code list} and subsequently adding it to this list.
 */
private void moveAllListNodes(DoublyLinkedList<E> list) {
    ListNode currentNode = list.head.getNext();
    for (; currentNode != null; currentNode = currentNode.getNext()) {
        list.removeListNode(currentNode);
        addListNode(currentNode);
    }
}

/**
 * Atomically moves all {@link ListNode}s from {@code list} to this list as if each node was removed with {@link #removeListNode(ListNodeImpl)}
 * from {@code list} and subsequently added to this list by {@link #addListNode(ListNodeImpl)}.
 */
private void moveAllListNodes(DoublyLinkedList<E> list) {
    ListNode head = list.getHead();
    ListNode tail = list.getTail();

    // If the list is empty, return immediately
    if (head == null && tail == null) {
        return;
    }

    // Remove the head node from the list
    ListNode temp = head;
    head = head.getNext();
    list.removeListNode(temp);

    // Add each node in the list to this list
    while (head != null) {
        addListNode(head);
        head = head.getNext();
    }

    // Check if the list is the last node in the list
    if (tail == null) {
        return;
    }

    // Add the tail node to the list
    addListNode(tail);
}

