/**
* Applies the given relative path to the given path, assuming standard Java folder separation (i.e. "/" separators).
* @param path the path to start from (usually a full file path)
* @param relativePath the relative path to apply (relative to the full file path above)
* @return the full file path that results from applying the relative path
*/
public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty paths
    if (path == null || path.isEmpty() || relativePath == null || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Invalid input");
    }

    // Split the path into its components
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Build the resulting path by merging the path components with the relative path components
    StringBuilder resultBuilder = new StringBuilder();
    for (int i = 0; i < pathComponents.length; i++) {
        if (i == 0 && !pathComponents[i].isEmpty()) {
            resultBuilder.append(pathComponents[i]);
        } else if (relativePathComponents[i].isEmpty()) {
            continue;
        } else if (relativePathComponents[i].equals("..")) {
            if (resultBuilder.length() > 1) {
                // Remove the last component of the result
                int lastSlashIndex = resultBuilder.lastIndexOf("/");
                resultBuilder.delete(lastSlashIndex, resultBuilder.length());
            }
        } else {
            // Add the current component to the result
            if (resultBuilder.length() > 0) {
                resultBuilder.append("/");
            }
            resultBuilder.append(relativePathComponents[i]);
        }
    }

    return resultBuilder.toString();
}

